import re

from moler.exceptions import ParsingDone
from moler.exceptions import CommandFailure
from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


class UeTraceStop(GenericEPCSIMCommand):
    """UeTraceStop command class."""

    def __init__(self, connection, ue_id, prompt=None, newline_chars=None, runner=None):
        """
        ue_trace_stop command.

        :param connection: moler connection to device, terminal when command is executed.
        :param ue_id: Id for stop trace for UE, accepts values 1-25000, required
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(UeTraceStop, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.ue_id = ue_id
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'ue_trace_stop'
        if self.ue_id:
            cmd = f'{cmd} id={self.ue_id}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_failure(line)
            except ParsingDone:
                pass
        return super(UeTraceStop, self).on_new_line(line, is_full_line)

    _re_failure1 = re.compile(r"Error:|ERR:")

    def _parse_failure(self, line):

        if self._regex_helper.search_compiled(UeTraceStop._re_failure1, line):
            self.set_exception(CommandFailure(self, f"Error: {line}"))
            raise ParsingDone


